// E2E-278: A refine prompt reaches the browser, exiting from it ends the run as a user exit, and the session is usable straight after
func TestE2E278(t *testing.T) {
	s := scenarios.New(t, "E2E-278")
	s.Given(`the "ai-refine-one-defect" project tree`)
	s.And(`the relay is running`)
	s.And(`a remote is running`)
	s.And(`the Product Owner dispatches "us-refine" for story "30.1" with fix as run "R1"`)
	s.And(`the Product Owner has the run page for run "R1" open`)
	s.And(`run "R1" publishes a "choice" prompt`)
	s.When(`the Product Owner chooses "exit" on the prompt of run "R1"`)
	s.Then(`run-output is non-empty`)
	s.And(`prompt-dialog has attribute "kind" = "choice"`)
	s.And(`run "R1" reaches a terminal state`)
	s.And(`run "R1" has outcome "user_exit"`)
	s.And(`run "R1" recorded events beyond the ones it had at the prompt`)
	s.And(`run-outcome has text "user_exit"`)
	s.And(`the remote spawned at most 6 AI calls`)
	s.And(`no file in the project tree changed`)
	s.And(`the session is listed`)
	s.And(`the session has no active run`)
	s.Done()
}

