// E2E-290: A real model turn asked through the workspace chat edits the document and the CLI persists it, along the same path a typed edit takes
func TestE2E290(t *testing.T) {
	s := scenarios.New(t, "E2E-290")
	s.Given(`the workspace is connected with a real model driving the chat`)
	s.And(`the Product Owner has the workspace "architecture" open`)
	s.And(`the Product Owner has opened the chat`)
	s.When(`the Product Owner asks the chat in prose to add a uniquely-named term`)
	s.Then(`file-view-editor contains the new term`)
	s.And(`"docs/architecture/architecture.yaml" holds the new term under its "terms" node`)
	s.And(`the browser's write receipt names that path and the file's hash`)
	s.And(`the relay's audit holds the CLI's receipt for the same work, revision and hash`)
	s.And(`the remote spawned at most 3 AI calls`)
	s.Done()
}
